import{bV as e,aL as r,u as t,G as o}from"./chunks/framework.C8THFwVE.js";const u=JSON.parse('{"title":"领导力原则","description":"","frontmatter":{"date":"2026-02-28T23:09:58.000Z","title":"领导力原则","permalink":"/growth/c3ae51","categories":["进化志"]},"headers":[],"relativePath":"01.进化志/04.领导力原则.md","filePath":"01.进化志/04.领导力原则.md"}'),l={name:"01.进化志/04.领导力原则.md"};function i(p,a,n,h,s,d){return r(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="领导力原则" tabindex="-1">领导力原则 <a class="header-anchor" href="#领导力原则" aria-label="Permalink to &quot;领导力原则&quot;">​</a></h1><p>亚马逊领导力准则：<a href="https://www.amazon.jobs/content/zh/our-workplace/leadership-principles" target="_blank" rel="noreferrer">https://www.amazon.jobs/content/zh/our-workplace/leadership-principles</a></p><p>书籍：《亚马逊逆向工作法》</p><h3 id="定义" tabindex="-1">定义 <a class="header-anchor" href="#定义" aria-label="Permalink to &quot;定义&quot;">​</a></h3><p>领导力原则描述了我们如何做事，如何领导团队或自己，以及如何“以客户为中心”进行决策和行动。</p><p>领导力原则的15个词条并没有先后顺序，但有一个根本原则：<strong>以客户为中心</strong></p><h3 id="极度关注客户" tabindex="-1">极度关注客户 <a class="header-anchor" href="#极度关注客户" aria-label="Permalink to &quot;极度关注客户&quot;">​</a></h3><p>每一个盈利性质的公司，其钱都是从客户手中来的，客户用钱决定公司的生死，<strong>必须把客户的利益放到第一位。</strong> 在美团的商业模式里，消费者就是客户，美团和商家一起服务于消费者，所以在利益方面，消费者第一，商家第二，美团第三</p><p><strong>如何实践：</strong></p><p>逆向工作法：通过听音、拎包、客户调研等方式，从客户需求触发，逆向回溯我们做什么，才能满足客户需求，解决客户问题。</p><p>领导力原则的其他14个词条，都是在践行如何关注客户</p><p>如何验证自己是否真的极度关注客户：</p><ol><li>你知道谁是你的客户吗 <ol><li>你的客户是美团的消费者或者商家吗</li><li>如果你直接服务于公司内部的合作伙伴，你是否了解他们是如何支持美团的消费者或商家的？</li></ol></li><li>你知道你的客户需要什么吗 <ol><li>客户最重要的需求是什么？客户的需求是如何变化的</li><li>那些因素会让客户对你的产品或服务感到失望</li><li>你的产品和服务，如何让客户吃的更好，生活更好</li></ol></li><li>你知道如何从客户触发，倒推工作吗 <ol><li>你们团队的产品和服务是如何被客户使用的</li><li>你的工作是否让客户体验更高效、更轻松、更愉快</li><li>你是否知道这些产品和服务的哪一部分，给客户造成了最大的困扰</li></ol></li></ol><p>其他问题：你是否提供了超越客户期望的产品和服务？你是否积极解决了客户的问题？你的决策是否符合客户的长期利益？</p><p>todo：互联网+大学：客户画像、同理心地图、旅程绘制 -&gt; 更好的了解客户</p><h3 id="主人翁精神" tabindex="-1">主人翁精神 <a class="header-anchor" href="#主人翁精神" aria-label="Permalink to &quot;主人翁精神&quot;">​</a></h3><p><strong>从长远考虑，不会为了短期业绩而牺牲长期价值。他们不仅仅代表自己的团队，而且代表整个公司行事。他们绝不会说“那不是我的工作”。</strong></p><p>有人可能会说，短期都做不好，凭什么要去思考长期？是的，没有什么选择是完美无缺的，永远都是在不同利弊下做权衡，那么兼容长期和短期，有一个好的方案是在满足基本短期需求时，更重视长期价值。 只考虑短期，那是投机。</p><p>这引申出局部和整体的辩证关系：局部利益最大化，往往会使整体利益受损；而整体利益最大化，会让各个局部利益相对合理，并将长期得以最大化</p><p>长期优于短期，整体优于局部，社会价值优于公司价值优于个人价值。</p><h3 id="创新并简化" tabindex="-1">创新并简化 <a class="header-anchor" href="#创新并简化" aria-label="Permalink to &quot;创新并简化&quot;">​</a></h3><p><strong>领导者期望并要求自己的团队进行创新和发明，并始终寻求使工作简化的方法。</strong> 他们了解外界动态，四处寻找新的创意，并且不局限于“非我发明”的观念。当我们开展新事物时，我们要接受被长期误解的可能。</p><p>这里的创新和发明，并不是让你创造一件事物出来，而是要多去想想，自己的工作/流程的哪些方面可以优化，以及怎么优化；客户的核心述求是什么，未来可能还有什么可能的需要。</p><p>简化，就是用更少实现更多，我们要主动有意识的去做简化。</p><p>人类有几千年的智慧，商业有上百年的历史，很多问题，都有成熟的解决方案和实践经验，抱有“非我发明”的心态，过分关注自我创新的产品，并不可取，站在巨人的肩膀上，我们更有机会做出有创造力的成果。</p><h3 id="力求正确" tabindex="-1">力求正确 <a class="header-anchor" href="#力求正确" aria-label="Permalink to &quot;力求正确&quot;">​</a></h3><p>领导者力求正确，他们拥有卓越的业务判断能力和敏锐的直觉。<strong>他们以科学方法做事，探求并遵循客观规律。他们寻求多样的视角，并力图否定自己原本相信的。</strong></p><p>这条是比较难的，每个人在主观上都会尽量的避免犯错，但是有可能会陷入一种误区，就是“我必须正确”，这种思维有几种常见的错误行为：</p><ol><li>不敢于做判断，怕错误，怕做出了错误的判断后，影响自己在别人心中的形象</li><li>自己做出了一个错误的判断，认为别人发现了这个错误，会看低自己，所以会去掩盖这个错误，还会选择性只看见利于自己的事情，无视否定自己的分析</li></ol><p>在面对不确定事物的时候，如何做？</p><ol><li>敢于做出决策和判断</li><li>“正确”是“力求”而来的，需要积极地寻找，就算可能会否定自己原先的判断的事实和分析。</li></ol><h3 id="好奇求知" tabindex="-1">好奇求知 <a class="header-anchor" href="#好奇求知" aria-label="Permalink to &quot;好奇求知&quot;">​</a></h3><p><strong>领导者从不停止学习，并不断寻找机会以提升自己。领导者对各种可能性充满好奇并付于行动加以探索，他们不怕失败，从失败中学习并成长。</strong></p><h3 id="苦练基本功" tabindex="-1">苦练基本功 <a class="header-anchor" href="#苦练基本功" aria-label="Permalink to &quot;苦练基本功&quot;">​</a></h3><p>基本功分为三类：通用基本功（听说读写想），管理基本功（工作管理），专业基本功（岗位能力）</p><p>苦练：刻意练习，不断提升</p><h3 id="选贤育能" tabindex="-1">选贤育能 <a class="header-anchor" href="#选贤育能" aria-label="Permalink to &quot;选贤育能&quot;">​</a></h3><p><strong>领导者不断提升招聘和晋升员工的标准。他们表彰杰出的人才，并乐于在组织中通过轮岗磨砺他们。领导者培养领导人才，他们严肃地对待自己育才树人的职责。领导者从员工角度出发，创建职业发展机制。</strong></p><p><a href="https://km.sankuai.com/page/411606225" target="_blank" rel="noreferrer">https://km.sankuai.com/page/411606225</a></p><h3 id="坚持最高标准" tabindex="-1">坚持最高标准 <a class="header-anchor" href="#坚持最高标准" aria-label="Permalink to &quot;坚持最高标准&quot;">​</a></h3><p><strong>领导者有着近乎严苛的高标准 ——— 这些标准在很多人看来可能高得不可理喻。领导者不断提高标准，激励自己的团队提供优质产品、服务和流程。领导者会确保任何问题不会蔓延，及时彻底解决问题并确保问题不再出现。</strong></p><h3 id="敢想" tabindex="-1">敢想 <a class="header-anchor" href="#敢想" aria-label="Permalink to &quot;敢想&quot;">​</a></h3><p><strong>局限性思考只能带来局限性的结果。</strong> 领导者不自我设限，不局限于当前资源，他们创造并沟通能激发结果的大胆方向。他们从不同角度不同方式考虑问题，并广泛寻找服务客户的方式。</p><p>要敢于建立大胆的愿景，不因为眼前资源的限制，降低为客户服务的目标，否则我们可能会被狭隘的想法限制，从而错失机会。</p><p>每一天都思考客户未来几年的需求，寻找新的大胆的方式提升客户体验</p><h3 id="崇尚行动" tabindex="-1">崇尚行动 <a class="header-anchor" href="#崇尚行动" aria-label="Permalink to &quot;崇尚行动&quot;">​</a></h3><p>速度对业务影响至关重要。很多决策和行动都可以改变，因此不需要进行过于广泛的推敲。<strong>我们提倡在深思熟虑前提下进行冒险。</strong></p><h3 id="勤俭节约" tabindex="-1">勤俭节约 <a class="header-anchor" href="#勤俭节约" aria-label="Permalink to &quot;勤俭节约&quot;">​</a></h3><p>力争以更少的投入实现更大的产出。勤俭节约可以让我们开动脑筋、自给自足并不断创新。增加人力、预算以及固定支出并不会为你赢得额外加分。</p><p><strong>核心其实是克服资源的有限性：以更有创造力，更聪明的方式优化和使用资源。</strong></p><h3 id="赢得信任" tabindex="-1">赢得信任 <a class="header-anchor" href="#赢得信任" aria-label="Permalink to &quot;赢得信任&quot;">​</a></h3><p>领导者专注倾听，坦诚沟通，尊重他人。领导者敢于自我批评，即便这样做会令自己尴尬或难堪。领导者实事求是，不粉饰，不夸大，不隐藏。他们并不会自我感觉良好，不认为自己团队总是对的，而是以最佳领导者和团队为标准来要求自己及其团队。</p><h3 id="刨根问底" tabindex="-1">刨根问底 <a class="header-anchor" href="#刨根问底" aria-label="Permalink to &quot;刨根问底&quot;">​</a></h3><p>领导者深入各个环节，随时掌控细节，频繁审核，当数据/指标与听到的个例不一致时持有怀疑态度。领导者不会遗漏任何工作。</p><p>随着对业务理解和经验的增长，领导者们可能会觉得以自己目前的级别，不应该再关注很多细节，而应该考虑更多宏观问题，这种行为有可能会导致，他们逐步丧失对业务的体感，并降低业务判断力，最终脱离业务。</p><p>当然，我们也应该避免过度的微观观测，导致钻入牛角尖还意识不到导致出不来，而是要把管理重点放到那些真正需要改进的地方。 如何应用： 1. 了解各种指标数据 2. 个性化客户反馈 3. 客户真实声音</p><p>验证： 1. 我是否已经知道这个案例背后的原因 2. 数据和指标是否已经提前反映了客户的真实需求</p><p>明确了问题本质后，就可以着手对工作流程和产品进行改进，你的客户也会因此受益。</p><p>保持观测（我们在做什么，客户在做什么） -&gt; 收集所有细节 -&gt; 形成观点 -&gt; 分析 -&gt; 做出判断</p><h3 id="敢于谏言-服从决定" tabindex="-1">敢于谏言，服从决定 <a class="header-anchor" href="#敢于谏言-服从决定" aria-label="Permalink to &quot;敢于谏言，服从决定&quot;">​</a></h3><p>领导者有义务在有不同意见时礼貌地挑战决定，哪怕这样做会不舒服或非常耗精力。领导者要信念坚定，矢志不移。他们不会为了关系和谐而妥协。一旦做出决定，他们就会全身心地致力于实现目标。</p><p>严忌：我也觉得这个决定不靠谱，但命令来了，我也只能这么干了</p><h3 id="达成业绩" tabindex="-1">达成业绩 <a class="header-anchor" href="#达成业绩" aria-label="Permalink to &quot;达成业绩&quot;">​</a></h3><p>领导者会关注其业务关键决定的前提条件，确保工作质量并及时完成。尽管遭受挫折，领导者依然勇于面对挑战，从不气馁。</p><p>正面例子： 面对客户续约率一直提不上来的问题，拜访数量，拜访频率，提案数量，这些“关键输入”都没问题，最后我们发现是质量除了问题，原因是销售没有做客户高层的定期经营汇报，导致续约决策人对过往合作没有感知和价值认知，从而影响了客户续约率。</p><p>其他领导力原则都可以作为达成业绩的输入。</p><h3 id="致力于成为全球最佳雇主" tabindex="-1">致力于成为全球最佳雇主 <a class="header-anchor" href="#致力于成为全球最佳雇主" aria-label="Permalink to &quot;致力于成为全球最佳雇主&quot;">​</a></h3><p>领导者致力于打造一个更安全、更高生产力、更高效、更多元、更公平的工作环境。领导者具备同理心，享受工作乐趣，并帮助他人也在工作中获得乐趣。领导者时常自省：团队成员在成长吗？他们是否被赋能？是否准备好迎接未来？领导者对员工的个人成功拥有愿景和承诺，无论这成功是在亚马逊还是在其他地方。</p><p>todo：亚马逊的“六页纸备忘录”制度</p><h3 id="成功和规模带来更大的责任" tabindex="-1">成功和规模带来更大的责任 <a class="header-anchor" href="#成功和规模带来更大的责任" aria-label="Permalink to &quot;成功和规模带来更大的责任&quot;">​</a></h3><p>亚马逊诞生于车库，但并未止步于此。亚马逊的业务规模庞大，对世界产生着影响，但我们还远非完美。我们必须时刻保持谦虚，并谨慎思考我们的行动带来的潜在影响。我们所在的社区、地球和后代需要我们每日精益求精做到更好。为了惠及客户、员工、合作伙伴以及全球更多人，我们必须抱着进步的决心开启每一天，并在每天结束时，深信明天可以更有作为。领导者要创造远超其所消费的更多价值，做到发现问题、并推动事物向更好的方向发展。</p>',71)])])}const b=e(l,[["render",i]]);export{u as __pageData,b as default};
